insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('7c108744-4d0e-5550-ab93-a9c8c5888591', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'In the figure, line $n$ intersects lines $r$ and $s$. Line $r$ is parallel to line $s$. What is the value of $x$?', '[]'::jsonb, 1, '![figure](/q/jun25/001.webp)'),
  ('0cf6576c-2c29-5e7e-bfe6-cb511914b8c0', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'The function $f$ is defined by $f(x) = 3^{x}$. The function $g$ is an increasing linear function. In the $xy$- plane, the graphs of $y = f(x)$ and $y = g(x)$ intersect at two points $(a,j)$ and $(b,k)$, where $j < k$. When $g(x) > f(x)$, which of the following must be true?', '["$x > k$", "$x < j$", "$x < j$ or $x > b$", "$a < x < b$"]'::jsonb, 2, null),
  ('dc26ada7-79a1-547a-8c6b-9c66725c3d87', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'If $4x = 7$, what is the value of $24x$?', '["$1$", "$13$", "$34$", "$42$"]'::jsonb, 3, null),
  ('7a4c456e-3eae-5ee2-9810-8376747252cd', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'Which expression is equivalent to $(x^{3} + 8x^{2} - 7x) + 6(x^{2} + 5)$?', '["$x^{3} + 6x^{2} - 7x + 30$", "$x^{3} + 8x^{2} - 7x + 30$", "$x^{3} + 14x^{2} - 7x + 30$", "$x^{3} + 5x^{2} - 7x + 30$"]'::jsonb, 4, null),
  ('b5afa7c0-72b8-5400-8d0b-285aa38483fe', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'The function $f$ is defined by $f(x) = x^{3} + 19$. What is the value of $f(2)$?', '[]'::jsonb, 5, null),
  ('b01ef194-a876-5c7b-bd77-748f9ca20211', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'The function $g$ is defined by $g(x) = \frac{x}{2}$. For what value of $x$ does $g(x) = 224$?', '[]'::jsonb, 6, null),
  ('8c8257a3-c717-5a6c-b5bf-48bf367cbe0f', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'The scatterplot shows the relationship between two variables, $x$ and $y$. Which of the following equations is the most appropriate linear model for the data shown?', '["$y = 0.8 + 8.5x$", "$y = 0.8 - 8.5x$", "$y = 8.5 + 0.8x$", "$y = 8.5 - 0.8x$"]'::jsonb, 7, '![figure](/q/jun25/002.webp)'),
  ('081e6f66-de84-5a76-8308-013f3249ca15', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'The $y$-intercept of the graph of $y = x^{2} + 15$ in the $xy$-plane is $(0,y)$. What is the value of $y$?', '[]'::jsonb, 8, null),
  ('731ad8ce-df4b-50e9-8461-2a4e61ac817e', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'For the given equation, which table gives three values of $x$ and their corresponding values of $y$?
$4x - 3y = -24$', '["$x$036\n\n$y$81216", "$x$036\n\n$y$16128", "$x$81216\n\n$y$036", "$x$81216\n\n$y$630"]'::jsonb, 9, null),
  ('788cba49-5579-5b2b-8d12-028d294b60b0', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'A chemist combines water and isopropanol to make a mixture with a volume of 38 milliliters (mL). The volume of isopropanol in the mixture is 10 mL. What is the volume of water, in mL, in the mixture? (Assume that the volume of the mixture is the sum of the volumes of water and isopropanol before they were mixed.)', '[]'::jsonb, 10, null),
  ('677d9317-17c7-5770-bc0b-e8d66e815a86', '11bf08da-666f-5bd9-8b4d-e52399fcee19', '$y = -\frac{1}{8}xy = \frac{1}{10}x$ The solution to the given system of equations is $(x,y)$. What is the value of $x$?', '["-8", "0", "2", "10"]'::jsonb, 11, null),
  ('6fdd42e2-132a-5b26-b607-9a1fc52e0a67', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'A company has a customer loyalty program. In January 2018, there were 800 customers enrolled in the loyalty program. For the next 24 months after January 2018, the total number of customers enrolled in the loyalty program each month was 5% greater than the total number enrolled the previous month, Which equation gives the total number of customers, $c$, enrolled in the company’s loyalty program $m$ months after January 2018, where $m < 24$?', '["$c = 800(0.05)^{m}$", "$c = 800(1.05)^{m}$", "$c = 800(1.5)^{m}$", "$c = 800(5)^{m}$"]'::jsonb, 12, null),
  ('b481bc5a-63a4-5034-b69e-b2207876f01d', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'The function $f(t) = 60,000(2)\frac{t}{580}$ gives the number of bacteria in a population $t$ minutes after an initial observation. How much time, in minutes, does it take for the number of bacteria in the population to double?', '[]'::jsonb, 13, null),
  ('d85cc207-fd93-5704-ad7a-34614c63f73e', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'For $x > 0$, the function $f$ is defined as follows: $f(x)$ equals 293% of $x$
Which of the following could describe this function?', '["Decreasing exponential", "Decreasing linear", "Increasing exponential", "Increasing linear"]'::jsonb, 14, null),
  ('215095f5-7547-5c0d-bce9-c54b3e595ce8', '11bf08da-666f-5bd9-8b4d-e52399fcee19', '$y = \frac{3}{8}x + 2$
One of two equations in a system of linear equations is given. The system has infinitely many solutions. What is the slope of the graph of the second equation?', '["$-\\frac{8}{3}$", "$-\\frac{3}{8}$", "$\\frac{3}{8}$", "$\\frac{8}{3}$"]'::jsonb, 15, null),
  ('8fb27d6e-4463-5fba-abd2-cbb23d225583', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'If $4x^{2} - 32x - 40 = 0$, what is the value of $x^{2} - 8x$?', '["0", "4", "8", "10"]'::jsonb, 16, null),
  ('c84f333d-2b43-5074-9f22-d8acffeca122', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'The function $f$ is defined by $f(x) = (x - 5)(x - 9)(x + k)$, where $k$ is a constant. In the $xy$-plane, the graph of $y = f(x)$ passes through the point $(-3,0)$. What is the value of $f(0)$?', '["-288", "-3", "11", "135"]'::jsonb, 17, null),
  ('e22b31ec-8c13-536a-a19e-a7efa99a01ba', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'Line $k$ is shown in the $xy$-plane. Line $j$ (not shown) is perpendicular to line $k$ and passes through the point $(-20,-23)$. Which equation defines line $j$?', '["$y = \\frac{3}{4}x - 8$", "$y = \\frac{3}{4}x - 38$", "$y = \\frac{4}{3}x - 8$", "$y = \\frac{4}{3}x - 38$"]'::jsonb, 18, '![figure](/q/jun25/003.webp)'),
  ('ac367d1b-4267-5ce2-844a-e11684beae78', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'In right triangle $ABC$, angles $A$ and $B$ are acute, side $AC$ has a length of $29.5$, and $\tan B = \frac{1}{9}$. What is the length of side $BC$, rounded to the nearest tenth?', '["870.2", "265.5", "5.4", "3.3"]'::jsonb, 19, null),
  ('92c7f235-3404-5b34-ace1-39213bd7e00e', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'A rectangular banner has an area of $3200$ square inches. A copy of the banner is made in which the length and width of the original banner are each increased by $20%$. What is the area of the copy, in square inches?', '["$3,220$", "$3,240$", "$3,840$", "$4,608$"]'::jsonb, 20, null),
  ('59696638-7324-5879-b9e1-f8b2c2f953a6', '11bf08da-666f-5bd9-8b4d-e52399fcee19', '$f(x) = (x - 4)^{2} + 6$
What is the minimum value of the given function?', '["2", "4", "6", "10"]'::jsonb, 21, null),
  ('c0a7235b-87e8-5f8b-8da4-5a20f42c4e1b', '11bf08da-666f-5bd9-8b4d-e52399fcee19', 'Point $F$ lies on a unit circle in the xy-plane and has coordinates $(1,0)$. Point $G$ is the center of the circle and has coordinates $(0,0)$. Point $H$ also lies on the circle and has coordinates $(-1,y)$, where $y$ is a constant. Which of the following could be the positive measure of angle $FGH$, in radians?', '["$\\frac{37π}{2}$", "$\\frac{39π}{2}$", "$34π$", "$35π$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('7c108744-4d0e-5550-ab93-a9c8c5888591', null, array['152']::text[], '**The correct answer is 152.** Line n is a transversal cutting the parallel lines r and s, so the marked angle 152° at the intersection with r and the angle x° at the intersection with s occupy the same relative position (both are at the intersection above their respective parallel line and on the same side of the transversal).
Corresponding angles formed by a transversal with parallel lines are congruent, so x = 152.
**Faster approach:** Whenever a transversal crosses two parallel lines, immediately check for corresponding or alternate interior angles: if the two marked angles are in the same relative position at each intersection, they are equal; if they are on the same side inside the parallels, they are supplementary. This lets you read off x without extra calculation.'),
  ('0cf6576c-2c29-5e7e-bfe6-cb511914b8c0', 3, null, '**Choice D is correct.** The exponential $f(x) = 3^{x}$ is increasing and convex upward, and $g$ is the unique line through $(a,j)$ and $(b,k)$ with $j < k$, so $b > a$. For a convex function the secant line through two points lies above the graph between those points, so $g(x) > f(x)$ for every $x$ strictly between $a$ and $b$; at $x = a$ and $x =$ $b$ they are equal, and outside $[a,b]$ the convex graph lies above the line.
**Choice A is incorrect.** Saying $x > k$ mixes an $x$-value with a $y$-value and is not even comparable to the intersection interval; moreover $g > f$ does not hold for all large $x$ (for $x > b$ we have $f(x) > g(x)$).
**Choice B is incorrect.** $x < j$ again mixes $x$ and $y$ and is wrong: for $x < a$ we have $f(x) > g(x)$, not $g(x) >$ $f(x)$.
**Choice C is incorrect.** $x < j$ or $x > b$ is wrong for the same reasons: the region where $g(x) > f(x)$ is between the intersection $a$ and $b$, not outside them.
**Faster approach:** Note that the line through two points of a convex-up curve lies above the curve between those points, so immediately conclude $g(x) > f(x)$ only for $a < x < b$ (test any point between $a$ and $b$ to confirm).'),
  ('dc26ada7-79a1-547a-8c6b-9c66725c3d87', 3, null, '**Choice D is correct.** Divide the equation $4x = 7$ by 4 to get $x = 7/4$. Multiply by 24 to find $24x = 24 \cdot \frac{7}{4} = 6 \cdot$ $7 = 42$, so 42 is the value of $24x$.
**Choice A is incorrect.** If $x = 7/4 \approx 1.75$, then $24x \approx 24 \cdot 1.75 = 42$, not 1; choice A is far too small.
**Choice B is incorrect.** 13 does not equal $24 \cdot \frac{7}{4}$; computing $24x$ exactly gives 42, so 13 is wrong.
**Choice C is incorrect.** 34 is not the product of 24 and $7/4$; the correct product is 42.
**Faster approach:** Multiply both sides of $4x = 7$ by 6 to get $24x = 42$ immediately without solving for $x$ first.'),
  ('7a4c456e-3eae-5ee2-9810-8376747252cd', 2, null, '**Choice C is correct.** Distribute and combine like terms: $(x^{3} + 8x^{2} - 7x) + 6(x^{2} + 5) = x^{3} + 8x^{2} - 7x +$ $6x^{2} + 30 = x^{3} + (8x^{2} + 6x^{2}) - 7x + 30 = x^{3} + 14x^{2} - 7x + 30$, which matches Choice C.
**Choice A is incorrect.** It has $6x^{2}$ instead of the correct combined $14x^{2}$; the $6$ was not added to $8$.
**Choice B is incorrect.** It leaves the $8x^{2}$ unchanged and fails to add the $6x^{2}$ from distributing the $6$.
**Choice D is incorrect.** It shows $5x^{2}$, which is neither the original $8x^{2}$ nor the sum $8x^{2} + 6x^{2} = 14x^{2}$; it’s not obtained by correct combining.
**Faster approach:** Distribute the $6$ to get $6x^{2} + 30$, then immediately combine the $x^{2}$ terms $8x^{2} + 6x^{2} = 14x^{2}$ to form the final expression.'),
  ('b5afa7c0-72b8-5400-8d0b-285aa38483fe', null, array['27']::text[], '**The correct answer is 27.** The function is defined by $f(x) = x^{3} + 19$. To evaluate $f(2)$, substitute $x = 2$ into the expression: $f(2) = 2^{3} + 19 = 8 + 19 = 27$. This gives the numeric value of the function at $x = 2$.
**Faster approach:** Direct substitution is the quickest method for evaluating a polynomial at a specific input: replace $x$ with the given number and compute. For small integers, compute the power first, then add constants to get the result.'),
  ('b01ef194-a876-5c7b-bd77-748f9ca20211', null, array['448']::text[], '**The correct answer is 448.** To find the value of $x$ such that $g(x) = 224$, we start with the definition of the function:
1. The function is given by:
$g(x) = \frac{x}{2}$
2. We set $g(x)$ equal to 224:
$\frac{x}{2} = 224$
3. To isolate $x$, we multiply both sides of the equation by 2:
$x = 224 \times 2$
4. Calculating the right side gives:
$x = 448$
Thus, the value of $x$ for which $g(x) = 224$ is 448.'),
  ('8c8257a3-c717-5a6c-b5bf-48bf367cbe0f', 3, null, '**Choice D is correct.** The cloud of points slopes downward, so the slope must be negative. Estimating from the plot: when $x \approx 0$, $y \approx 10$, and when $x \approx 10$, $y \approx 2$, so the slope is about $(2 - 10)/(10 - 0) = -8/10 =$ $-0.8$. An intercept near $8.5$ (close to the actual plotted $∼ 10$) with slope $-0.8$ matches the trend shown, so $y = 8.5 - 0.8x$ is the most appropriate linear model.
**Choice A is incorrect.** It has a large positive slope $8.5$, but the data show a clear negative relationship (as $x$ increases, $y$ decreases).
**Choice B is incorrect.** Although the slope is negative, $-8.5$ is far too steep for the gradual decline in the scatterplot; the predicted $y$ values would drop to large negative numbers by $x = 2$ or $3$, which is inconsistent with the points.
**Choice C is incorrect.** It gives a positive slope $0.8$, but the data show $y$ decreasing as $x$ increases, so the slope should be negative.
**Faster approach:** Estimate slope by using two roughly endpoint points and computing rise/run to get the sign and approximate magnitude (here $(2 - 10)/(10 - 0) \approx -0.8$), then pick the choice with that sign and magnitude.'),
  ('081e6f66-de84-5a76-8308-013f3249ca15', null, array['15']::text[], '**The correct answer is 15.** The y-intercept of a graph is the point where $x = 0$. Substituting $x = 0$ into the equation $y = x^{2} + 15$ gives $y = 0^{2} + 15 = 15$, so the y-intercept is $(0,15)$.
**Faster approach:** Immediately set $x = 0$ in any function to find the y-intercept; for $y = x^{2} + 15$ this yields $y = 15$ without additional algebra.'),
  ('731ad8ce-df4b-50e9-8461-2a4e61ac817e', 0, null, '**Choice A is correct.** Rearranging $4x - 3y = -24$ gives $-3y = -24 - 4x$, so $y = \frac{4}{3}x + 8$. For $x = 0$, $y = 8$; for $x = 3$, $y = \frac{4}{3}(3) + 8 = 4 + 8 = 12$; for $x = 6$, $y = \frac{4}{3}(6) + 8 = 8 + 8 = 16$, which matches the table in choice A.
**Choice B is incorrect.** It lists $y = 16$ when $x = 0$, but substituting $x = 0$ into the equation gives $y = 8$, so the first entry is wrong.
**Choice C is incorrect.** In C the listed $x$ and $y$ values are swapped relative to the tested pairs; substituting $x = 8$ into the equation does not produce $y = 0$, so the pairs do not satisfy the equation.
**Choice D is incorrect.** For $x = 8$ the equation yields $y = \frac{4}{3}(8) + 8 \ne 6$, so the entries in D do not satisfy the line.
**Faster approach:** Solve for $y$ as $y = \frac{4}{3}x + 8$ and then quickly plug each given $x$ into that formula (or plug each table pair into the original equation) to see which table’s pairs satisfy the equation.'),
  ('788cba49-5579-5b2b-8d12-028d294b60b0', null, array['28']::text[], '**The correct answer is 28.** Let $w$ represent the volume of water (in mL). The total volume is the sum of the water and isopropanol, so $w + 10 = 38$. Solving gives $w = 38 - 10 = 28$. Thus the mixture contains 28 mL of water.
**Faster approach:** Subtract the isopropanol volume from the total volume: $38 - 10 = 28$. This subtraction works for every question that asks for one part given the total and the other part.'),
  ('677d9317-17c7-5770-bc0b-e8d66e815a86', 1, null, '**Choice B is correct.** The two equations represent lines $y = -\frac{1}{8}x$ and $y = \frac{1}{10}x$. At their intersection the $y$- values are equal, so $-\frac{1}{8}x = \frac{1}{10}x$. Subtracting gives $(-\frac{1}{8} - \frac{1}{10})x = 0$, i.e. $-\frac{9}{40}x = 0$, so $x = 0$.
**Choice A is incorrect.** Substituting $x = -8$ gives $y = 1$ from the first equation and $y = -0.8$ from the second, so the pair does not satisfy both equations.
**Choice C is incorrect.** Substituting $x = 2$ yields $y = -\frac{1}{4}$ and $y = \frac{1}{5}$, which are not equal, so $x = 2$ is not a solution.
**Choice D is incorrect.** Substituting $x = 10$ gives $y = -\frac{10}{8} = -1.25$ and $y = 1$ from the other equation, so $x = 10$ does not satisfy both equations.
**Faster approach:** Both lines are proportional to $x$ (they pass through the origin), so their only possible intersection is at the origin; immediately conclude $x = 0$ for any such pair of nonidentical lines.'),
  ('6fdd42e2-132a-5b26-b607-9a1fc52e0a67', 1, null, '**Choice B is correct.** The number of customers grows by 5% each month, so each month the total is multiplied by $1 + 0.05 = 1.05$. Starting with 800 customers at $m = 0$, after $m$ months the amount is $800(1.05)^{m}$, which matches choice B.
**Choice A is incorrect.** $800(0.05)^{m}$ would represent repeatedly multiplying by $0.05$ (a 95% decrease each month), not a 5% increase.
**Choice C is incorrect.** $1.5$ is a 50% increase factor, not a 5% increase; $800(1.5)^{m}$ grows far too quickly.
**Choice D is incorrect.** Multiplying by $5^{m}$ has no relation to a 5% monthly increase; it represents multiplying by 5 each month.
**Faster approach:** For percent growth, use factor $1 + extrate$; here the factor is $1.05$, so write $800(1.05)^{m}$ every time.'),
  ('b481bc5a-63a4-5034-b69e-b2207876f01d', null, array['580']::text[], '**The correct answer is 580.** To find the doubling time, set $f(t)$ equal to twice its initial value: $60,000 \cdot 2^{t/580} =$ $2 \cdot 60,000$. Dividing both sides by $60,000$ gives $2^{t/580} = 2$. Because $2 = 2^{1}$, equate exponents to get $t/580 = 1$, so $t = 580$ minutes.
**Faster approach:** Recognize that the exponent form $2^{t/580}$ equals 2 when $t/580 = 1$, so the doubling time is the denominator of the exponent’s fraction, $580$ minutes. This direct-exponent comparison works for any function of the form $A \cdot 2^{t/k}$ to find the doubling time.'),
  ('d85cc207-fd93-5704-ad7a-34614c63f73e', 3, null, '**Choice D is correct.** The function $f(x)$ is defined as $f(x) = 293% \cdot x$. This indicates that for every unit increase in $x$, the value of $f(x)$ increases by a factor of 2.93. Specifically, this means:
Since $293%$ is greater than $100%$, the slope of the function is positive, making it increasing. The function is also linear because it can be expressed in the standard form of a linear function, $f(x) = mx + b$, where $m = 2.93$ and $b = 0$ (in this case, the function passes through the origin).
Therefore, this function is an **increasing linear** function, confirming that Choice D is the correct answer.
Choices A, B, and C are incorrect because:
**Choice A (Decreasing exponential):** An exponential function typically increases or decreases based on the base, and since $f(x)$ is linear with a positive slope, it cannot be decreasing or exponential. **Choice B (Decreasing linear):** A decreasing linear function has a negative slope. However, since $f(x)$ has a positive slope (as established), it cannot be decreasing.
**Choice C (Increasing exponential):** Although it correctly indicates an increasing function, the exponential nature implies a nonlinear growth rate that is not present in $f(x)$, which is purely linear.'),
  ('215095f5-7547-5c0d-bce9-c54b3e595ce8', 2, null, '**Choice C is correct.** For a system of two linear equations to have infinitely many solutions, the two equations must represent the same line. The given line has slope $\frac{3}{8}$, so the second equation must have the same slope, $\frac{3}{8}$.
**Choice A is incorrect.** The slope $-\frac{8}{3}$ is the negative reciprocal of $\frac{3}{8}$, not equal to it, so it would produce a different line (in fact, the perpendicular line), giving at most one intersection point.
**Choice B is incorrect.** The slope $-\frac{3}{8}$ has the correct magnitude but the opposite sign, so the second line would be different and intersect the first at a single point unless intercepts also matched in a way that is impossible with opposite slopes.
**Choice D is incorrect.** The slope $\frac{8}{3}$ is the reciprocal of $\frac{3}{8}$ and not equal to it, so it would produce a different line and not yield infinitely many solutions.
**Faster approach:** For infinite solutions, require identical lines; immediately match the slope of the given equation.'),
  ('8fb27d6e-4463-5fba-abd2-cbb23d225583', 3, null, '**Choice D is correct.** Divide the given equation by 4 to get $x^{2} - 8x - 10 = 0$. Rearranging gives $x^{2} - 8x = 10$, which matches choice D.
**Choice A is incorrect.** That would require $x^{2} - 8x = 0$, but from the equation we found $x^{2} - 8x = 10$, so A is not true.
**Choice B is incorrect.** Substituting $4$ for $x^{2} - 8x$ contradicts the derived equality $x^{2} - 8x = 10$; 4 does not satisfy the relation.
**Choice C is incorrect.** Similarly, $8$ does not satisfy $x^{2} - 8x = 10$, so choice C is not correct.
**Faster approach:** Simplify the original equation by dividing by 4 and then isolate the target expression: from $x^{2} - 8x - 10 = 0$ immediately get $x^{2} - 8x = 10$.'),
  ('c84f333d-2b43-5074-9f22-d8acffeca122', 3, null, '**Choice D is correct.** Since $f(-3) = 0$, one of the factors equals 0 when $x = -3$. Plugging in gives $(-3 -$ $5)(-3 - 9)(-3 + k) = (-8)(-12)(k - 3) = 96(k - 3) = 0$, so $k = 3$. Then $f(0) = (0 - 5)(0 - 9)(0 + 3) =$ $(-5)(-9)(3) = 45 \cdot 3 = 135$, which matches Choice D.
**Choice A is incorrect.** If $k = 3$ (required by $f(-3) = 0$) then $f(0) = 135$, not $-288$; $-288$ would come from a different value of $k$.
**Choice B is incorrect.** $-3$ is not equal to the computed value $135$ when $k = 3$, so it cannot be $f(0)$.
**Choice C is incorrect.** $11$ does not match the product $(-5)(-9)(3) = 135$ that results from the necessary $k = 3$.
**Faster approach:** Use the given root: $f(-3) = 0$ means one factor is zero at $x = -3$, so set $-3 + k = 0$ to get $k = 3$, then directly compute $f(0)$.'),
  ('e22b31ec-8c13-536a-a19e-a7efa99a01ba', 0, null, '**Choice A is correct.** Line j is perpendicular to line k, so its slope is the negative reciprocal of the slope of k. From the graph, line k has slope $-\frac{4}{3}$, so line j has slope $\frac{3}{4}$. Using point-slope with the given point $(-20,-23)$: $-23 = \frac{3}{4}(-20) + b = -15 + b$, so $b = -8$. Thus the equation is $y = \frac{3}{4}x - 8$, which matches choice A. **Choice B is incorrect.** It has the correct slope $\frac{3}{4}$ but the wrong $y$-intercept; plugging $x = -20$ gives $y =$ $-15 - 38 = -53$, not $-23$.
**Choice C is incorrect.** Its slope $\frac{4}{3}$ is the same sign and reciprocal of the slope of j, not the negative reciprocal, so it is not perpendicular to line k.
**Choice D is incorrect.** It also has the wrong slope for a line perpendicular to k (and the $y$-intercept $-38$ does not make the line pass through $(-20,-23)$).
**Faster approach:** Determine the slope of k from the graph, take the negative reciprocal for the perpendicular slope, then substitute the given point to find the intercept; finally match the resulting slope-intercept form to the choices.'),
  ('ac367d1b-4267-5ce2-844a-e11684beae78', 1, null, '**Choice B is correct.** Because the triangle is right and angles A and B are acute, angle C is the right angle. For angle B, the side opposite is $AC$ and the side adjacent (the other leg) is $BC$, so $\tan B = \frac{AC}{BC}$. Given $\tan B =$ $\frac{1}{9}$ and $AC = 29.5$, solve $\frac{29.5}{BC} = \frac{1}{9}$, so $BC = 9 \cdot 29.5 = 265.5$, which to the nearest tenth is $265.5$. **Choice A is incorrect.** That value, $870.2$, is $29.5 \times 29.5$ and has no relation to the tangent ratio here.
**Choice C is incorrect.** $5.4$ is far too small: it would make $AC/BC > 1$, contradicting $\tan B = 1/9 < 1$.
**Choice D is incorrect.** $3.3$ is also inconsistent with $AC/BC = 1/9$ because $29.5/3.3 \approx 8.94$, not $1/9$.
**Faster approach:** Identify opposite and adjacent for the given acute angle, write $\tan = \text{opposite}/\text{adjacent}$, and solve directly — here multiply the given opposite by 9 to get the adjacent.'),
  ('92c7f235-3404-5b34-ace1-39213bd7e00e', 3, null, '**Choice D is correct.** If each linear dimension is increased by $20%$, each is multiplied by $1.20$. Area scales by the square of the linear scale factor, so the new area is $3200 \times (1.20)^{2} = 3200 \times 1.44 = 4608$ square inches.
**Choice A is incorrect.** $3220$ is only $20$ more than the original area and does not account for the multiplicative effect of increasing both dimensions.
**Choice B is incorrect.** $3240$ similarly is far too small; it does not reflect the $1.44$ area scale factor from increasing both length and width by $20%$.
**Choice C is incorrect.** $3840$ equals $3200 \times 1.2$, which would be the area if only one dimension were increased by $20%$, not both.
**Faster approach:** Multiply the original area by $(1 + 0.20)^{2} = 1.44$ whenever both linear dimensions are increased by $20%$; this gives the new area directly.'),
  ('59696638-7324-5879-b9e1-f8b2c2f953a6', 2, null, '**Choice C is correct.** The function is already in vertex form $f(x) = (x - 4)^{2} + 6$. Because $(x - 4)^{2} \ge 0$ for all real $x$, the smallest possible value of that square is $0$, which occurs at $x = 4$. Substituting $x = 4$ gives $f(4) =$ $0 + 6 = 6$, so the minimum value is $6$.
**Choice A is incorrect.** A value of $2$ is less than the constant term $6$, and since $(x - 4)^{2}$ cannot be negative, the function cannot achieve $2$.
**Choice B is incorrect.** A minimum of $4$ would require $(x - 4)^{2} = -2$, which is impossible because squares are nonnegative.
**Choice D is incorrect.** A value of $10$ is attainable (for example $x = 6$ gives $(6 - 4)^{2} + 6 = 4 + 6 = 10$) but it is not the minimum; it is larger than the minimum value $6$.
**Faster approach:** Recognize the vertex form $a(x - h)^{2} + k$; the minimum (for $a > 0$) is $k$, reached at $x = h$. Here $k = 6$.'),
  ('c0a7235b-87e8-5f8b-8da4-5a20f42c4e1b', 3, null, '**Choice D is correct.** Since the circle is unit and centered at $G = (0,0)$, $H = (-1,y)$ must satisfy $(-1)^{2} +$ $y^{2} = 1$, so $y = 0$ and $H = (-1,0)$. The central angle $\angle FGH$ between $F = (1,0)$ and $H = (-1,0)$ is $π$ radians. Any valid positive measure could be $π$ plus an integer multiple of $2π$, i.e. $(2k + 1)π$ for integer $k \ge 0$. Choice D, $35π$, equals $(2 \cdot 17 + 1)π$, so it is coterminal with $π$ and therefore possible.
**Choice A is incorrect.** $\frac{37π}{2} = 18.5π$ is not an odd integer multiple of $π$, so it is not coterminal with $π$. **Choice B is incorrect.** $\frac{39π}{2} = 19.5π$ is not an odd integer multiple of $π$, so it is not coterminal with $π$.
**Choice C is incorrect.** $34π$ is an even multiple of $π$; even multiples correspond to $0$ mod $2π$, not $π$, so it cannot represent the central angle.
**Faster approach:** Recognize the two points are diametrically opposite so the central angle is $π$. Check which choice is an odd integer multiple of $π$ (i.e., of the form $(2k + 1)π$); that choice is correct.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
